<template><v-dialog v-model="library.pickerOpen" max-width="500" :z-index="11050"><section class="library-panel"><header><h2>Adicionar à playlist</h2><button @click="library.pickerOpen=false" aria-label="Fechar playlists">✕</button></header><p>{{ library.pickerTracks.length }} músicas selecionadas · repetidas serão ignoradas</p><label>Playlist<select v-model="selected"><option value="">Criar uma playlist</option><option v-for="p in library.playlists" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label v-if="!selected">Nome<input v-model="name" maxlength="80" placeholder="Meu repertório"/></label><p v-if="error" role="alert">{{ error }}</p><button class="primary" :disabled="busy" @click="save">{{ busy?'Salvando…':'Adicionar músicas' }}</button><router-link to="/Playlists" @click="library.pickerOpen=false">Organizar minhas playlists</router-link></section></v-dialog></template>
<script setup>import { ref,watch } from 'vue';import { useLibraryStore } from '@/stores/useLibraryStore';const library=useLibraryStore(),selected=ref(''),name=ref(''),busy=ref(false),error=ref('');watch(()=>library.pickerOpen,()=>{error.value='';selected.value='';name.value=''});async function save(){busy.value=true;error.value='';const uid=library.owner;try{const id=selected.value||await library.create(name.value);if(uid!==library.owner)return;await library.add(id,library.pickerTracks);library.pickerOpen=false}catch(e){error.value=e.message}finally{busy.value=false}}</script>